/* nd_gconv.h: the symbol map of the gfx table tool (S7CONV; host only). gconv_sym[] is generated by gen_gfx_syms.py. */
#ifndef ND_GCONV_H
#define ND_GCONV_H
enum { GS_GFX = 1, GS_VTX, GS_IMG };
typedef struct GSym {
    const char* name;
    int kind;
    const void* addr;
    const void* end;
} GSym;
extern const GSym gconv_sym[];
extern const unsigned gconv_nsym;
#endif
